"""Plan prices and coupons (moved over from the old billing monolith)."""

from decimal import Decimal, ROUND_HALF_UP

PLAN_PRICES = {"starter": 9.99, "team": 49.0, "business": 199.0}
COUPONS = {"WELCOME10": 10, "PARTNER25": 25}


def list_price(plan_code: str) -> float:
    try:
        return PLAN_PRICES[plan_code]
    except KeyError:
        raise ValueError(f"unknown plan {plan_code!r}") from None


def apply_coupon(price: float, coupon: str) -> float:
    if coupon not in COUPONS:
        raise ValueError(f"unknown coupon {coupon!r}")
    return round(price * (100 - COUPONS[coupon]) / 100, 2)


def add_tax(amount, rate_percent):
    """Gross amount including ``rate_percent`` percent tax.

    The result is rounded to the cent using decimal arithmetic so that
    monetary values are not distorted by binary floating point.
    """
    if isinstance(rate_percent, bool) or not isinstance(rate_percent, (int, float, Decimal)):
        raise ValueError(f"invalid tax rate {rate_percent!r}")
    rate = Decimal(str(rate_percent))
    if not rate.is_finite() or rate < 0 or rate > 100:
        raise ValueError(f"tax rate must be between 0 and 100, got {rate_percent!r}")
    if isinstance(amount, bool) or not isinstance(amount, (int, float, Decimal)):
        raise ValueError(f"invalid amount {amount!r}")
    base = Decimal(str(amount))
    if not base.is_finite():
        raise ValueError(f"invalid amount {amount!r}")
    return (base * (1 + rate / 100)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
class BillingError(Exception):
    """Raised for any invalid billing operation.

    ``code`` is a short machine-readable reason such as ``"negative_amount"``;
    ``message`` is optional human-readable detail.
    """

    def __init__(self, code: str, message: str = ""):
        super().__init__(f"{code}: {message}" if message else code)
        self.code = code
        self.message = message
# Changelog

